for (const item of $input.all()) {
  const body = item.json.body || item.json;
  if (!body.fileBase64) throw new Error('Multi-invoice webhook payload is missing fileBase64.');
  const fileName = body.fileName || 'document.pdf';
  const extension = fileName.toLowerCase().split('.').pop();
  const mimeTypes = { pdf: 'application/pdf', doc: 'application/msword', docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', txt: 'text/plain' };
  const inputFileMimeType = body.mimeType || mimeTypes[extension] || 'application/octet-stream';
  const isPdf = extension === 'pdf' || inputFileMimeType === 'application/pdf';
  item.json = { ...item.json, ...body, fileName, extension, inputFileMimeType, isPdf, rawText: body.rawOcrText || body.ocrText || '' };
  item.binary = { data: { data: body.fileBase64, fileName, mimeType: inputFileMimeType } };
}
return $input.all();

const webhook = $node['Multi Invoice Webhook'].json.body || {};
const boundaryPattern = /(?:^|\n)\s*(?:TAX\s+INVOICE|FREIGHT\s+INVOICE|COMMERCIAL\s+INVOICE|INVOICE)\b[\s\S]{0,500}?(?:invoice\s*(?:number|no\.?|#)|inv\s*#|bill\s*to|shipment\s*(?:number|no\.?|#)|tracking\s*(?:number|no\.?|#))/i;

return $input.all().flatMap((item) => {
  const input = item.json || {};
  const detectedInvoiceCount = Number(input.detectedInvoiceCount ?? webhook.detectedInvoiceCount ?? 0);
  const detectedInvoiceGroups = Array.isArray(input.detectedInvoiceGroups) ? input.detectedInvoiceGroups : (Array.isArray(webhook.detectedInvoiceGroups) ? webhook.detectedInvoiceGroups : null);
  const documentId = input.documentId || webhook.documentId;
  const callbackUrl = input.callbackUrl || webhook.callbackUrl;

  console.log('[Detect Separate Invoices] detectedInvoiceCount=', detectedInvoiceCount, 'groups=', detectedInvoiceGroups?.length ?? 0);
  if (detectedInvoiceGroups && detectedInvoiceGroups.length >= 2) {
    if (detectedInvoiceCount > 1 && detectedInvoiceGroups.length !== detectedInvoiceCount) throw new Error(`Detected invoice count ${detectedInvoiceCount} does not match supplied invoice groups ${detectedInvoiceGroups.length}.`);
    const invoiceCount = detectedInvoiceCount > 1 ? detectedInvoiceCount : detectedInvoiceGroups.length;
    const output = detectedInvoiceGroups.map((group, groupPosition) => {
      const invoiceIndex = Number.isInteger(group.invoiceIndex) ? group.invoiceIndex : groupPosition;
      const rawOcrText = String(group.rawOcrText || '').trim();
      if (!rawOcrText) throw new Error(`Invoice group ${invoiceIndex} has no rawOcrText.`);
      console.log('[Detect Separate Invoices] group=', invoiceIndex, 'pages=', group.pageStart, '-', group.pageEnd, 'invoiceNumber=', (rawOcrText.match(/invoice\s*(?:number|no\.?|#)\s*[:#]?\s*([A-Z0-9-]+)/i) || [])[1] || 'not found');
      return { json: { documentId, callbackUrl, invoiceIndex, invoiceCount, pageStart: group.pageStart, pageEnd: group.pageEnd, rawOcrText } };
    });
    if (detectedInvoiceCount > 1 && output.length !== detectedInvoiceCount) throw new Error(`Generated ${output.length} invoice items but detectedInvoiceCount is ${detectedInvoiceCount}.`);
    return output;
  }

  const rawText = String(input.rawText || input.text || input.data || webhook.rawOcrText || '').trim();
  if (!rawText) throw new Error('No extractable text found. For DOC/DOCX uploads, provide rawOcrText when the n8n Extract From File node cannot decode the source format.');
  const pages = rawText.split(/\f|(?:^|\n)\s*---\s*PAGE\s+\d+\s*---\s*(?:\n|$)/gim).map((text) => text.trim()).filter(Boolean);
  const pageBlocks = pages.length ? pages : [rawText];
  const groups = [];
  pageBlocks.forEach((pageText, pageIndex) => {
    const startsInvoice = pageIndex > 0 && boundaryPattern.test(pageText);
    if (startsInvoice || groups.length === 0) groups.push({ pageStart: pageIndex + 1, pageEnd: pageIndex + 1, pages: [pageText] });
    else { groups[groups.length - 1].pageEnd = pageIndex + 1; groups[groups.length - 1].pages.push(pageText); }
  });
  if (detectedInvoiceCount > 1 && groups.length !== detectedInvoiceCount) throw new Error(`Fallback generated ${groups.length} invoice groups but detectedInvoiceCount is ${detectedInvoiceCount}.`);
  console.log('[Detect Separate Invoices] fallback groups=', groups.length);
  return groups.map((group, invoiceIndex) => ({ json: { documentId, callbackUrl, invoiceIndex, invoiceCount: groups.length, pageStart: group.pageStart, pageEnd: group.pageEnd, rawOcrText: group.pages.join('\n\f\n') } }));
});

