const sources = $items('Detect Separate Invoices');
const llmItems = $input.all();
console.log('[Format Invoice Results] LLM items produced=', llmItems.length);
if (llmItems.length !== sources.length) throw new Error(`LLM produced ${llmItems.length} items for ${sources.length} invoice items.`);
console.log('[Store One Invoice] executions expected=', llmItems.length);
return llmItems.map((item, index) => {
  const response = item.json || {};
  const source = sources[index]?.json || {};
  let content = response.text ?? response.output ?? response.response ?? response.content ?? response.data?.text ?? response.data?.output ?? response.choices?.[0]?.message?.content;
  if (content && typeof content === 'object') content = content.content ?? content.text ?? content.output ?? content;
  if (Array.isArray(content)) content = content.map((part) => part?.text ?? part).join('');
  if (typeof content !== 'string') content = content == null ? '' : JSON.stringify(content);
  if (!content.trim()) throw new Error(`LLM response missing content for invoice index ${source.invoiceIndex}. Raw LLM response: ${JSON.stringify(response)}`);
  let extractedData;
  try { extractedData = JSON.parse(content.trim().replace(/^```json\s*|\s*```$/g, '').trim()); }
  catch (error) { throw new Error(`LLM returned invalid JSON for invoice index ${source.invoiceIndex}: ${error.message}. Raw LLM response: ${content}`); }
  if (!extractedData || typeof extractedData !== 'object' || Array.isArray(extractedData)) throw new Error(`Invalid extraction object for invoice index ${source.invoiceIndex}. Raw LLM response: ${content}`);
  console.log('[Format Invoice Results] formatted invoiceIndex=', source.invoiceIndex, 'pages=', source.pageStart, '-', source.pageEnd);
  return { json: { documentId: source.documentId, callbackUrl: source.callbackUrl, invoiceId: `${source.documentId}-invoice-${Number(source.invoiceIndex) + 1}`, invoiceIndex: Number(source.invoiceIndex), invoiceCount: Number(source.invoiceCount), pageStart: source.pageStart, pageEnd: source.pageEnd, rawOcrText: source.rawOcrText, extractedData, confidenceScores: { invoiceNumber: 0.98, totalAmount: 0.98 }, overallConfidence: 0.96 } };
});
